//! Vertical adjustment database of the auto-hinter.

/// Raise the top of a glyph above the highest contour below it.
pub(super) const UP: u16 = 0x01;
/// Lower the bottom of a glyph below the lowest contour above it.
pub(super) const DOWN: u16 = 0x02;
/// Like `UP`, but for the second highest contour.
pub(super) const UP2: u16 = 0x04;
/// Like `DOWN`, but for the second lowest contour.
pub(super) const DOWN2: u16 = 0x08;
/// The top contour is a tilde that is stretched and aligned.
pub(super) const TILDE_TOP: u16 = 0x10;
/// The bottom contour is a tilde that is stretched and aligned.
pub(super) const TILDE_BOTTOM: u16 = 0x20;
/// Like `TILDE_TOP`, but for the second highest contour.
pub(super) const TILDE_TOP2: u16 = 0x40;
/// Like `TILDE_BOTTOM`, but for the second lowest contour.
pub(super) const TILDE_BOTTOM2: u16 = 0x80;
/// Ignore the top blue zone of capital letters.
pub(super) const IGNORE_CAPITAL_TOP: u16 = 0x100;
/// Ignore the bottom blue zone of capital letters.
pub(super) const IGNORE_CAPITAL_BOTTOM: u16 = 0x200;
/// Ignore the top blue zone of small letters.
pub(super) const IGNORE_SMALL_TOP: u16 = 0x400;
/// Ignore the bottom blue zone of small letters.
pub(super) const IGNORE_SMALL_BOTTOM: u16 = 0x800;
/// Do not limit the height of the adjusted contour.
pub(super) const NO_HEIGHT_CHECK: u16 = 0x1000;
/// No adjustment.
pub(super) const NONE: u16 = 0;

