/// Returns the adjustment flags for `codepoint`, or `NONE`.
///
/// This is FreeType's `af_adjustment_database_lookup`: a binary search over
/// `ADJUSTMENT_DATABASE`. A `mid` of zero that moves `high` below zero ends
/// the search, where FreeType's unsigned index would wrap around.
pub(super) fn lookup(codepoint: u32) -> u16 {
    let mut low: isize = 0;
    let mut high: isize = ADJUSTMENT_DATABASE.len() as isize - 1;
    while high >= low {
        let mid = (low + high) / 2;
        let (mid_codepoint, flags) = ADJUSTMENT_DATABASE[mid as usize];
        if mid_codepoint < codepoint {
            low = mid + 1;
        } else if mid_codepoint > codepoint {
            high = mid - 1;
        } else {
            return flags;
        }
    }
    NONE
}
